class Pet:
    def __init__(self, name):
        self.name = name
        self.happiness = 50

    def feed(self):
        self.happiness += 10

class Ship:
    def __init__(self, name, cargo):
        self.name = name
        self.cargo = cargo

    def __str__(self):
        return f"{self.name} gemisi, yük: {self.cargo}"

print(Ship("Martı", 12))

class Hero:
    def __init__(self, name):
        self.name = name

class Wizard(Hero):
    def cast(self):
        return f"{self.name} büyü yaptı!"

w = Wizard("Merlin")
print(w.cast())

